import React, { useState, useEffect } from "react";
import {
  Box, Typography, Button, Card, CardContent, IconButton, Menu, MenuItem, TextField
} from "@mui/material";
import { initDatabase, saveUserData,getAllUsers } from "../database";
import { useNavigate } from "react-router-dom";
import AccountCircleIcon from "@mui/icons-material/AccountCircle";
import SkipNextIcon from "@mui/icons-material/SkipNext";
import ArrowDropDownIcon from '@mui/icons-material/ArrowDropDown';
import SkipPreviousIcon from "@mui/icons-material/SkipPrevious";
import bgiquiz from "../assets/quizbgi.jpg";
import quizData from "../services/quizquestions.json";
import { logLogout } from "../utils/analytics";



const PuzzleQuiz = () => {


  const [db, setDb] = useState(null);
  const loggedInUser = localStorage.getItem("loggedInUser");
  const [quizStart, setQuizStart] = useState(false);
  const [authenticated, setAuthenticated] = useState(false);
  const [companyName, setCompanyName] = useState("Rudhra Info Solutions");
  const [username, setUsername] = useState(loggedInUser);
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [selectedAnswer, setSelectedAnswer] = useState(null);
  const [answeredCount, setAnsweredCount] = useState(0);
  const [missedCount, setMissedCount] = useState(0);
  const [timer, setTimer] = useState(10); // Set 10 seconds for each question
  const [anchorEl, setAnchorEl] = useState(null);
  const navigate = useNavigate();
  const [successMessage, setSuccessMessage] = useState("");
  const [users, setUsers] = useState([]);

  // **Initialize database when the page loads**
  useEffect(() => {
    async function setupDB() {
      const database = await initDatabase();
      setDb(database);

      // Fetch and log all users
    const users = await getAllUsers(database);
    console.log("All Users:", users);
    }
    setupDB();

  }, []);

  const timestamp = new Date().toLocaleString();


  const username1 = loggedInUser
    ? loggedInUser.charAt(0).toUpperCase() + loggedInUser.slice(1)
    : "";

  const questions = quizData.questions;

  // Timer logic
  useEffect(() => {
    if (timer === 0) {
      setMissedCount((prev) => prev + 1);
      handleNextQuestion();
    }

    const countdown = setTimeout(() => {
      setTimer((prev) => prev - 1);
    }, 1000);

    return () => clearTimeout(countdown);
  }, [timer]);

  // Reset timer for each new question
  useEffect(() => {
    setTimer(10); // Reset to 10 seconds for each new question
  }, [currentQuestionIndex]);

  const handleAnswerSelection = (option) => {
    setSelectedAnswer(option);

    if (option === questions[currentQuestionIndex].correctAnswer) {
      setAnsweredCount((prev) => prev + 1);
    } else {
      setMissedCount((prev) => prev + 1);
    }

    setTimeout(() => {
      handleNextQuestion();
    }, 1000);
  };

  const handleNextQuestion = () => {
    if (currentQuestionIndex + 1 < questions.length) {
      setCurrentQuestionIndex((prevIndex) => prevIndex + 1);
      setSelectedAnswer(null);
    } else {
      navigate("/quiz-completed");
    }
  };

  const handleLogout = () => {
    const loginTime = localStorage.getItem("loginTime");
    const sessionDuration = loginTime ? (Date.now() - loginTime) / 1000 : 0; // in seconds

    const username = localStorage.getItem("loggedInUser");

    // Track logout event
    logLogout(username, sessionDuration);

    // Clear session data
    localStorage.removeItem("loggedInUser");
    localStorage.removeItem("loginTime");

    alert(`User ${username} was logged in for ${sessionDuration} seconds.`);
    localStorage.clear();
    navigate("/");
  };

  // **Updated handleAuthentication()**
  async function handleAuthentication() {
    if (!db) {
      console.error("Database is not initialized.");
      return;
    }

    if (!username || !companyName) {
      setError("Username and Company Name are required.");
      return;
    }

    setAuthenticated(true);

    // Insert user data into SQLite
    await saveUserData(db, username, companyName, timestamp);

    console.log("User stored successfully!");
  }



  return (
    <Box sx={{ position: "relative", height: "100vh", display: "flex", flexDirection: "column", justifyContent: "center", alignItems: "center", overflow: "hidden" }}>
      <img src={bgiquiz} alt="Background" style={{ position: "absolute", top: 0, left: 0, width: "100%", height: "100%", objectFit: "cover", zIndex: -1 }} />

      {/* Header */}
      <Box sx={{ backgroundColor: "#1976d2", color: "white", display: "flex", alignItems: "center", justifyContent: "space-between", width: "50%", height: "8%", borderRadius: "50px 0 0 50px", padding: "10px 20px", alignSelf: "flex-end" }}>
        <Typography variant="h5">Quiz</Typography>
        <Box display="flex" alignItems="center" gap={1}>
          <AccountCircleIcon fontSize="large" />
          <Typography variant="h6">{username1}</Typography>
          <IconButton onClick={(e) => setAnchorEl(e.currentTarget)}>
            <ArrowDropDownIcon sx={{ color: "white" }} />
          </IconButton>
          <Menu anchorEl={anchorEl} open={Boolean(anchorEl)} onClose={() => setAnchorEl(null)}>
            <MenuItem onClick={handleLogout}>Logout</MenuItem>
          </Menu>
        </Box>
      </Box>

      {/* Content */}
      <Box sx={{ flexGrow: 1, display: "flex", alignItems: "center", justifyContent: "center", padding: "20px", position: "relative" }}>
        <Card sx={{ width: "650px", height: "320px", padding: "30px", boxShadow: 3, borderRadius: 3, position: "relative", backgroundColor: "rgba(255, 255, 255, 0.1)", backdropFilter: "blur(5px)" }}>
          {!authenticated ? (
            <CardContent>
              <Typography variant="h4" textAlign="center" fontWeight="bold" color="white">
                🔒 Authentication
              </Typography>
              <Box sx={{
                maxHeight: "200px", // Scrollable height
                overflowY: "auto",
                padding: 2,
                "&::-webkit-scrollbar": {
                  width: "8px",
                },
                "&::-webkit-scrollbar-track": {
                  background: "#2c2c2c",
                  borderRadius: "4px",
                },
                "&::-webkit-scrollbar-thumb": {
                  background: "#888",
                  borderRadius: "4px",
                },
                "&::-webkit-scrollbar-thumb:hover": {
                  background: "#555",
                },
              }}>
                {/* Disabled Username Field */}
                <TextField
                  label="Username"
                  variant="outlined"
                  fullWidth
                  value={username}
                  inputProps={{ style: { color: "white" }, readOnly: true }}
                  sx={{ mb: 2 }}
                />

                {/* Company Name Field */}
                <TextField
                  label="Company Name"
                  variant="outlined"
                  fullWidth
                  value={companyName}
                  onChange={(e) => setCompanyName(e.target.value)}
                  inputProps={{ style: { color: "white" }, readOnly: true }}
                  sx={{ mb: 2 }}
                />

                {/* Timestamp Field (Non-Editable) */}
                <TextField
                  label="Timestamp"
                  variant="outlined"
                  fullWidth
                  value={new Date().toLocaleString()}
                  inputProps={{ style: { color: "white" }, readOnly: true }}
                  sx={{ mb: 2 }}
                />

                {/* Password Field */}
                <TextField
                  label="Password"
                  type="password"
                  variant="outlined"
                  fullWidth
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  sx={{ mb: 2 }}
                />

                {error && <Typography color="error" textAlign="center" sx={{ mb: 2 }}>{error}</Typography>}

                {/* Authentication Button */}
                <Button variant="contained" color="primary" onClick={handleAuthentication}>
                  Verify User
                </Button>
              </Box>
            </CardContent>

          ) : quizStart ? <>
            {/* Timer Display */}
            <Typography variant="h6" sx={{ textAlign: "center", color: timer <= 3 ? "red" : "white", fontWeight: "bold" }}>
              ⏳ {timer} sec
            </Typography>

            {/* Back & Skip Buttons */}
            <Box sx={{ position: "absolute", top: 10, right: 10, display: "flex", gap: 1 }}>
              <IconButton onClick={() => setCurrentQuestionIndex((prev) => Math.max(prev - 1, 0))} disabled={currentQuestionIndex === 0} sx={{ color: currentQuestionIndex === 0 ? "#ccc" : "#08abed" }}>
                <SkipPreviousIcon />
              </IconButton>
              <IconButton onClick={handleNextQuestion} sx={{ color: "#08abed" }}>
                <SkipNextIcon />
              </IconButton>
            </Box>

            <CardContent>
              <Typography variant="h6" color="#f0d8d8" fontWeight="bold" textAlign="center">🚀 Puzzle Challenge</Typography>
              <Typography variant="subtitle1" textAlign="center" fontWeight="bold" mb={2} sx={{ color: "#fff" }}>
                <b>Q{currentQuestionIndex + 1}.</b> {questions[currentQuestionIndex].question}
              </Typography>
              <Box display="flex" flexDirection="column" gap={1}>
                {questions[currentQuestionIndex].options.map((option, index) => (
                  <Button key={index} variant="contained" onClick={() => handleAnswerSelection(option)} disabled={selectedAnswer !== null} sx={{
                    background: selectedAnswer === option
                      ? option === questions[currentQuestionIndex].correctAnswer
                        ? "green"
                        : "red"
                      : "#08abed",
                    color: "white",
                    fontWeight: "bold",
                    textTransform: "none",
                    textAlign: "left",
                    justifyContent: "flex-start",
                  }}>
                    {String.fromCharCode(97 + index)}. {option}
                  </Button>
                ))}
              </Box>
            </CardContent>
          </> :
            <CardContent>
              <Typography variant="h4" textAlign="center" fontWeight="bold" color="white">🎉 Welcome to the Quiz!</Typography>
              <Typography variant="subtitle1" textAlign="center" color="white" mt={2}>Let's test your knowledge. Click below to begin!</Typography>
              <Box display="flex" justifyContent="center" mt={4}>
                <Button variant="contained" color="success" onClick={() => setQuizStart(true)}>Start Quiz</Button>
              </Box>
            </CardContent>

          }
        </Card>
      </Box>

      {/* Footer */}
      <Box sx={{ backgroundColor: "#1976d2", color: "white", height: "8%", width: "50%", borderRadius: "0 50px 50px 0", padding: "10px", alignSelf: "flex-start", textAlign: "center", display: "flex", alignItems: "center", justifyContent: "center", fontWeight: "bold" }}>
        📋 Attempted: {answeredCount + missedCount} | ✅ Correct: {answeredCount} | ❌ Wrong: {missedCount}
      </Box>
    </Box>
  );
};

export default PuzzleQuiz;


