import React, { useState, useEffect } from "react";
import { Grid, Paper, Typography, TextField, Button, Snackbar, Alert } from "@mui/material";
import { useNavigate } from "react-router-dom";
import { useFormik } from "formik";
import * as Yup from "yup";
import salesforcesimg from "../assets/salesforceimg.png";
import rislogo from "../assets/rislogo.png";
import userLoginData from "../services/userlogin.json";
import { initGA, logPageView, logLogin } from "../utils/analytics";
import { trackAdobeEvent } from "../utils/adobeAnalytics";

const LoginScreen = () => {
    const navigate = useNavigate();
    const [openSnackbar, setOpenSnackbar] = useState(false);
    const [successSnackbar, setSuccessSnackbar] = useState(false);

    useEffect(() => {
        initGA();
        logPageView();

        // If already logged in, redirect to /pdf-viewer
        const loggedInUser = localStorage.getItem("loggedInUser");
        if (loggedInUser) {
            navigate("/pdf-viewer");
        }
    }, [navigate]);

    const formik = useFormik({
        initialValues: {
            username: "",
            password: "",
        },
        validationSchema: Yup.object({
            username: Yup.string()
                .min(3, "Username must be at least 3 characters")
                .required("Username is required"),
            password: Yup.string()
                .min(6, "Password must be at least 6 characters")
                .required("Password is required"),
        }),
        onSubmit: (values) => {
            const user = userLoginData.users.find(
                (user) => user.username === values.username && user.password === values.password
            );

            if (user) {
                const loginTime = Date.now();
                localStorage.setItem("loggedInUser", values.username);
                localStorage.setItem("loginTime", loginTime);

                console.log(`User ${values.username} logged in.`);  // Debugging

                // Track login in Google Analytics & Adobe Analytics
                logLogin(values.username);
                trackAdobeEvent("user_login", { user_id: values.username, timestamp: new Date().toISOString() });

                setSuccessSnackbar(true);

                setTimeout(() => {
                    navigate("/pdf-viewer");
                }, 500);
            } else {
                setOpenSnackbar(true);
            }
        },
    });

    return (
        <Grid container style={{ height: "100vh", justifyContent: "center", alignItems: "center", background: "#7bb0c9" }}>
            <Grid container style={{ height: "80%", width: "90%", borderRadius: "20px", overflow: "hidden", boxShadow: "0px 4px 10px rgba(0, 0, 0, 0.2)" }}>
                <Grid item xs={12} md={7} style={{ backgroundImage: `url(${salesforcesimg})`, backgroundSize: "cover", backgroundPosition: "center", display: "flex", flexDirection: "column", justifyContent: "center", alignItems: "center", padding: "2rem" }}>
                    <Typography variant="h5" gutterBottom style={{ color: "#03122b", fontWeight: "bold" }}>
                        Welcome to RIS Interview Preparation Portal
                    </Typography>
                </Grid>
                <Grid item xs={12} md={5} style={{ display: "flex", justifyContent: "center", alignItems: "center", backgroundColor: "#bde1f2" }}>
                    <Paper elevation={5} style={{ padding: "2rem", width: "70%", maxWidth: "400px", borderRadius: "20px", backgroundColor: "#f7f9fa" }}>
                        <img src={rislogo} alt="Company Logo" style={{ width: "100px", marginBottom: "1rem" }} />
                        <form onSubmit={formik.handleSubmit}>
                            <TextField
                                fullWidth
                                placeholder="Username"
                                margin="normal"
                                variant="outlined"
                                name="username"
                                value={formik.values.username}
                                onChange={formik.handleChange}
                                onBlur={formik.handleBlur}
                                error={formik.touched.username && Boolean(formik.errors.username)}
                                helperText={formik.touched.username && formik.errors.username}
                            />
                            <TextField
                                fullWidth
                                placeholder="Password"
                                type="password"
                                margin="normal"
                                variant="outlined"
                                name="password"
                                value={formik.values.password}
                                onChange={formik.handleChange}
                                onBlur={formik.handleBlur}
                                error={formik.touched.password && Boolean(formik.errors.password)}
                                helperText={formik.touched.password && formik.errors.password}
                            />
                            <Button
                                fullWidth
                                variant="contained"
                                type="submit"
                                style={{ marginTop: "1.5rem", background: "linear-gradient(135deg, #0061F2, #4f85e4)", color: "white", borderRadius: "25px", fontWeight: "bold" }}
                            >
                                LOGIN
                            </Button>
                        </form>
                    </Paper>
                </Grid>
            </Grid>

            <Snackbar open={openSnackbar} autoHideDuration={6000} onClose={() => setOpenSnackbar(false)}>
                <Alert severity="error">Invalid username or password!</Alert>
            </Snackbar>
            <Snackbar open={successSnackbar} autoHideDuration={3000} onClose={() => setSuccessSnackbar(false)}>
                <Alert severity="success">Login Successful! Redirecting...</Alert>
            </Snackbar>
        </Grid>
    );
};

export default LoginScreen;
