import initSqlJs from "sql.js";
import { Buffer } from "buffer";

// Function to initialize SQLite database
export async function initDatabase() {
  const SQL = await initSqlJs({ locateFile: (file) => `https://sql.js.org/dist/${file}` });

  let db;

  // Check if database exists in localStorage
  const storedDb = localStorage.getItem("sqliteDB");
  if (storedDb) {
    const binaryData = Uint8Array.from(atob(storedDb), c => c.charCodeAt(0));
    db = new SQL.Database(binaryData);
  } else {
    db = new SQL.Database();
    createUsersTable(db);
  }

  return db;
}

// Function to create 'users' table
function createUsersTable(db) {
  db.run(`
    CREATE TABLE IF NOT EXISTS users (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      username TEXT NOT NULL,
      companyName TEXT NOT NULL,
      timestamp TEXT NOT NULL
    );
  `);

  // Save the updated database to localStorage
  localStorage.setItem("sqliteDB", Buffer.from(db.export()).toString("base64"));
}

// Function to insert user data
export async function saveUserData(db, username, companyName, timestamp) {
  createUsersTable(db); // Ensure table exists before inserting data

  const stmt = db.prepare("INSERT INTO users (username, companyName, timestamp) VALUES (?, ?, ?)");
  stmt.run([username, companyName, timestamp]);
  stmt.free(); // Free the statement memory

  // Save database to localStorage
  localStorage.setItem("sqliteDB", Buffer.from(db.export()).toString("base64"));
}

// Function to retrieve all user data
export async function getAllUsers(db) {
  createUsersTable(db); // Ensure table exists before querying
  const result = db.exec("SELECT * FROM users");
  return result.length > 0 ? result[0].values : [];
}
